package dev.jobflow.service;
import com.fasterxml.jackson.databind.ObjectMapper; import dev.jobflow.domain.*; import dev.jobflow.repo.JobAttemptRepository; import io.micrometer.core.instrument.*; import java.time.*; import java.util.*; import java.util.concurrent.*; import org.slf4j.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*;
@Service @ConditionalOnProperty(name="jobflow.worker.enabled",havingValue="true",matchIfMissing=true) public class JobWorker {private static final Logger log=LoggerFactory.getLogger(JobWorker.class);private final JobService jobs;private final List<JobExecutor> executors;private final JobAttemptRepository attempts;private final RetryPolicy retry;private final Duration lease;private final ExecutorService pool;private final Counter completed,failed,retried,dead; public JobWorker(JobService j,List<JobExecutor> e,JobAttemptRepository a,RetryPolicy r,@Value("${jobflow.worker.lease-duration}")Duration l,@Value("${jobflow.worker.concurrency}")int c,MeterRegistry m){jobs=j;executors=e;attempts=a;retry=r;lease=l;pool=Executors.newFixedThreadPool(c);completed=m.counter("jobflow.jobs.completed");failed=m.counter("jobflow.jobs.failed");retried=m.counter("jobflow.jobs.retried");dead=m.counter("jobflow.jobs.dead_letter");}
 @Scheduled(fixedDelayString="${jobflow.worker.poll-delay-ms}") public void poll(){for(int i=0;i<32;i++){Optional<Job> j=jobs.claimNext(lease);if(j.isEmpty())break;pool.submit(()->process(j.get().getId()));}} @Scheduled(fixedDelay=30000) public void recover(){int n=jobs.recoverExpired().size();if(n>0)log.warn("Recovered {} expired job leases",n);} public void process(UUID id){Job j;try{j=jobs.processing(id);var attempt=new JobAttempt(j);attempts.save(attempt);JobExecutor executor=executors.stream().filter(e->e.supports(j.getType())).findFirst().orElseThrow(()->new JobExecutionException("UNSUPPORTED_TYPE","No executor",false));long start=System.nanoTime();try{var result=executor.execute(j.getPayload());jobs.complete(id,result);attempt.finish("COMPLETED",null);completed.increment();}catch(JobExecutionException e){jobs.fail(id,e.code(),e.getMessage(),e.retryable(),Instant.now().plus(retry.delayFor(j.getAttemptCount())));attempt.finish(e.retryable()?"RETRY_WAIT":"DEAD_LETTER",e.getMessage());failed.increment();if(e.retryable()&&j.getAttemptCount()<j.getMaxAttempts())retried.increment();else dead.increment();}catch(Exception e){jobs.fail(id,"UNEXPECTED", "Execution failed",true,Instant.now().plus(retry.delayFor(j.getAttemptCount())));attempt.finish("RETRY_WAIT","Unexpected executor error");failed.increment();}finally{attempts.save(attempt);}}catch(Exception e){log.error("Job {} processing failed",id,e);}}
}
